package org.apache.commons.lang.text;

import java.io.*;
import java.io.Reader;
import java.io.Writer;
import java.math.*;
import java.util.*;
import java.util.Collection;
import java.util.Iterator;
import java.util.List;
import org.apache.commons.lang.ArrayUtils;
import org.apache.commons.lang.SystemUtils;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class StrBuilder_appendFixedWidthPadRight_TriageGen0Test {

    private StrBuilder strBuilder;

    @Before
    public void setUp() {
        strBuilder = new StrBuilder();
    }

    @Test
    public void testAppendFixedWidthPadRight_WidthZero() {
        strBuilder.append("base");
        strBuilder.appendFixedWidthPadRight("test", 0, ' ');
        // width <= 0 should do nothing to the buffer and return this
        Assert.assertEquals("base", strBuilder.toString());
        Assert.assertEquals(4, strBuilder.length());
    }

    @Test
    public void testAppendFixedWidthPadRight_WidthNegative() {
        strBuilder.append("base");
        strBuilder.appendFixedWidthPadRight("test", -5, ' ');
        // width <= 0 should do nothing
        Assert.assertEquals("base", strBuilder.toString());
    }

    @Test
    public void testAppendFixedWidthPadRight_ObjectIsNull() {
        strBuilder.setNullText("NULL");
        strBuilder.appendFixedWidthPadRight(null, 6, '.');
        // str becomes "NULL", len 4, width 6. Pad 2 dots.
        Assert.assertEquals("NULL..", strBuilder.toString());
    }

    @Test
    public void testAppendFixedWidthPadRight_ObjectIsNotNull_PaddingNeeded() {
        strBuilder.appendFixedWidthPadRight("abc", 5, '*');
        // str "abc" (len 3), width 5. Pad 2 stars.
        Assert.assertEquals("abc**", strBuilder.toString());
    }

    @Test
    public void testAppendFixedWidthPadRight_ObjectIsNotNull_NoPaddingNeeded() {
        strBuilder.appendFixedWidthPadRight("abcdef", 3, '*');
        // str "abcdef" (len 6), width 3. strLen >= width.
        // The code uses str.getChars(0, width, buffer, size)
        // Note: The implementation provided truncates the string to the width if strLen >= width
        Assert.assertEquals("abc", strBuilder.toString());
    }

    @Test
    public void testAppendFixedWidthPadRight_ObjectIsNotNull_ExactWidth() {
        strBuilder.appendFixedWidthPadRight("abc", 3, '*');
        // str "abc" (len 3), width 3. strLen == width.
        Assert.assertEquals("abc", strBuilder.toString());
    }

    @Test
    public void testAppendFixedWidthPadRight_Chaining() {
        strBuilder.appendFixedWidthPadRight("A", 3, '.')
                  .appendFixedWidthPadRight("B", 2, '!');
        // "A.." + "B!"
        Assert.assertEquals("A..B!", strBuilder.toString());
    }

    @Test
    public void testAppendFixedWidthPadRight_IntegerObject() {
        strBuilder.appendFixedWidthPadRight(123, 5, '0');
        // "123" (len 3), width 5. Pad 2 zeros.
        Assert.assertEquals("12300", strBuilder.toString());
    }

    @Test
    public void testAppendFixedWidthPadRight_LargeWidth() {
        strBuilder.appendFixedWidthPadRight("x", 10, '#');
        Assert.assertEquals("x#########", strBuilder.toString());
        Assert.assertEquals(10, strBuilder.length());
    }
}
